// Body of a REF registered with `kb add-ref`. {id} and {title} are substituted.
export const REF_BODY = {
  "en": "# {id}: {title}\n\n<!-- The originals listed in `files` are SEALED: never edit, rename or replace them.\n     A new version from the sender = `kb add-ref` again, then set `supersedes: [{id}]` on the new REF.\n     This body is our notes about the material and may be edited. -->\n\n## Summary\n\n<!-- What this material is and what it covers. AI may draft; the owner confirms. -->\n\n## Used by\n\n<!-- Which API / BR / REQ rely on it. Link from those documents: related: - {{id: {id}, rel: derived_from}} -->\n\n## Notes\n",
  "zh-TW": "# {id}：{title}\n\n<!-- `files` 中列出的原文已封存：不得編輯、更名或替換。\n     對方給了新版本 = 再執行一次 `kb add-ref`，並在新的 REF 上設定 `supersedes: [{id}]`。\n     本文件的內文是「我們對這份資料的筆記」，可以編輯。 -->\n\n## 摘要\n\n<!-- 這份資料是什麼、涵蓋哪些範圍。AI 可起草，由負責人確認。 -->\n\n## 被哪些知識使用\n\n<!-- 哪些 API / BR / REQ 依據這份資料。由那些文件連過來：related: - {{id: {id}, rel: derived_from}} -->\n\n## 備註\n"
};
